import * as orig from './orig.mjs';
import * as neu from './new.mjs';
import assert from 'node:assert/strict';

const names = ['kim','lee','park','choi','jung'];
const rnd = (n) => Math.floor(Math.random() * n);
const row = () => ({ id: rnd(10), name: names[rnd(5)], age: 18 + rnd(43) });
const rows = () => Array.from({ length: rnd(13) }, row);

const same = (a, b, label) => {
  const ja = JSON.stringify(a), jb = JSON.stringify(b);
  if (ja !== jb || typeof a !== typeof b) throw new Error(`${label}: orig=${ja} new=${jb}`);
};

// Example inputs from the spec
const exRows = [
  [{"id":3,"name":"kim","age":20},{"id":0,"name":"kim","age":21},{"id":3,"name":"park","age":55},{"id":6,"name":"choi","age":30},{"id":1,"name":"park","age":33},{"id":5,"name":"choi","age":23},{"id":6,"name":"park","age":46}],
  [{"id":1,"name":"choi","age":35},{"id":0,"name":"lee","age":19},{"id":0,"name":"lee","age":57},{"id":3,"name":"choi","age":27}],
  [{"id":2,"name":"choi","age":18},{"id":5,"name":"kim","age":26},{"id":4,"name":"kim","age":25},{"id":2,"name":"jung","age":22}],
  [{"id":7,"name":"kim","age":22},{"id":2,"name":"jung","age":60}],
  []
];
for (const r of exRows) {
  same(orig.byId(r), neu.byId(r), 'byId example');
  same(orig.totalAge(r), neu.totalAge(r), 'totalAge example');
}
for (const v of [{}, [""], "", "x", null, true, false, 0, 42, -5, 99, [], [[]], [1], {a:{}}, {a:1}, [{}], "abc"]) {
  same(orig.isBlank(v), neu.isBlank(v), 'isBlank example ' + JSON.stringify(v));
}

// Random property checks over the stated input range
for (let i = 0; i < 20000; i++) {
  const r = rows();
  same(orig.byId(r), neu.byId(r), 'byId random');
  same(orig.totalAge(r), neu.totalAge(r), 'totalAge random');
}
const randJson = (depth) => {
  const k = rnd(depth > 0 ? 8 : 5);
  switch (k) {
    case 0: return null;
    case 1: return rnd(2) === 0;
    case 2: return rnd(105) - 5;
    case 3: return ['', 'a', 'kim', ' '][rnd(4)];
    case 4: return rnd(2) ? 0 : 1.5;
    case 5: return Array.from({ length: rnd(4) }, () => randJson(depth - 1));
    case 6: { const o = {}; for (let j = rnd(4); j > 0; j--) o['k' + rnd(5)] = randJson(depth - 1); return o; }
    default: return [];
  }
};
for (let i = 0; i < 20000; i++) {
  const v = randJson(2);
  same(orig.isBlank(v), neu.isBlank(v), 'isBlank random ' + JSON.stringify(v));
}
console.log('all equal');
EOF
cd "$S" && node compare.mjs

